#!/usr/bin/env bash
# step199 — dark-theme the order confirmation page + the invoice page to match the
# storefront. Logic unchanged; palette/fonts swapped to the dark design system.
# Invoice prints clean (light) via @media print. Standalone views (no partials).
set -uo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
cd "$GSZ" || { echo "FATAL: no $GSZ"; exit 1; }

FILES=(views/order.ejs views/invoice.ejs)
for f in "${FILES[@]}"; do cp -p "$f" "$f.bak-step199-$TS"; done
echo "backups: *.bak-step199-$TS"
restore(){ echo "!! restoring"; for f in "${FILES[@]}"; do [ -f "$f.bak-step199-$TS" ] && cp -p "$f.bak-step199-$TS" "$f"; done; }
trap 'restore' ERR

base64 -d > views/order.ejs <<'OEOF'

OEOF
base64 -d > views/invoice.ejs <<'IEOF'

IEOF

node -e "const ejs=require('$GSZ/node_modules/ejs'),fs=require('fs');['views/order.ejs','views/invoice.ejs'].forEach(function(f){ejs.compile(fs.readFileSync('$GSZ/'+f,'utf8'),{filename:'$GSZ/'+f});console.log('ejs ok: '+f);});" || { echo 'EJS COMPILE FAILED'; restore; exit 2; }
grep -q -- '--paper:#080a14' views/order.ejs && grep -q -- '--paper:#080a14' views/invoice.ejs || { echo 'VERIFY FAILED: dark palette missing'; restore; exit 3; }
echo "verify ok: dark order + invoice written"

trap - ERR
pm2 restart gsz --update-env >/dev/null 2>&1 || pm2 restart gsz >/dev/null 2>&1
ok=0
for i in $(seq 1 25); do
  code=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true)
  if [ "$code" = "200" ]; then ok=1; echo "health ok (HTTP 200) after ${i} tries"; break; fi
  sleep 0.6
done
[ "$ok" = "1" ] || { echo "HEALTH CHECK FAILED (last: ${code:-none}) — restoring"; restore; pm2 restart gsz >/dev/null 2>&1; exit 4; }
echo "STEP199 DONE — order + invoice pages are now dark-themed."
